//! Actual LX7 S32I/L32I drive exact 4G-board RMT and SDMMC/IDMAC routes.
//! No modem, network or manufacturer-firmware compatibility claim.
use emu_core::{Bus,Core};
use esp_soc::{SocBus,Stop};
use esp_periph::sdmmc::{self,reg,des0,int,CMD_START,CMD_RESP,CMD_DATA,CMD_WRITE,CMD_RESP_LONG,CTRL_USE_INTERNAL_DMA,CTRL_INT_ENABLE,BMOD_DE};
const PC:u32=0x4037_0000;const SD:u32=0x6002_8000;const RAM:u32=esp32s3::bus::DRAM_LOW+0x1000;
const BOARDS:[&str;2]=["waveshare-s3-a7670e-4g-v2","waveshare-s3-sim7670g-4g-v2"];
struct Guest{m:esp32s3::Machine}
impl Guest{
 fn new(name:&str)->Self{let mut m=esp32s3::machine([0;6]);m.bus.board=esp32s3::board::make_board(name).unwrap();m.bus.attach_board_devices();m.bus.set_flash_size(16<<20);m.bus.set_psram_size(8<<20).unwrap();m.bus.load_bytes(PC,&[0x32,0x64,0,0x52,0x24,0]).unwrap();m.cores[0].ps=0;m.cores[0].set_jit(false);Self{m}}
 fn put(&mut self,a:u32,v:u32){self.m.cores[0].pc=PC;self.m.cores[0].set_ar(4,a);self.m.cores[0].set_ar(3,v);assert!(matches!(self.m.run(1),Stop::MaxInsns));assert_eq!(self.m.cores[0].pc,PC+3);}
 fn get(&mut self,a:u32)->u32{self.m.cores[0].pc=PC+3;self.m.cores[0].set_ar(4,a);assert!(matches!(self.m.run(1),Stop::MaxInsns));assert_eq!(self.m.cores[0].pc,PC+6);self.m.cores[0].get_ar(5)}
 fn route(&mut self,p:u32,s:u32){self.put(0x6000_9004+4*p,1<<12|1<<9);self.put(0x6000_4554+4*p,s);if s<256{self.put(0x6000_4154+4*s,0x80|p);}}
 fn sd_wiring(&mut self){for(p,s)in[(5,173),(4,179),(6,213)]{self.route(p,s);}let c=self.get(0x600c_001c);self.put(0x600c_001c,c|1<<7);let r=self.get(0x600c_0024);self.put(0x600c_0024,r&!(1<<7));}
 fn cmd(&mut self,n:u8,arg:u32,flags:u32)->u32{self.put(SD+reg::RINTSTS,u32::MAX);self.put(SD+reg::CMDARG,arg);self.put(SD+reg::CMD,CMD_START|1<<16|u32::from(n)|flags);self.get(SD+reg::RESP0)}
 fn ready(&mut self){self.cmd(0,0,0);assert_eq!(self.cmd(8,0x1aa,CMD_RESP),0x1aa);for _ in 0..2{self.cmd(55,0,CMD_RESP);self.cmd(41,0x40ff8000,CMD_RESP);}self.cmd(2,0,CMD_RESP|CMD_RESP_LONG);let rca=self.cmd(3,0,CMD_RESP)&0xffff0000;self.cmd(7,rca,CMD_RESP);self.put(SD+reg::CTYPE,0);}
 fn sector(&mut self,n:u8,buffer:u32){for(i,v)in[des0::OWN|des0::FS|des0::LD,512,buffer,0].into_iter().enumerate(){self.put(RAM+i as u32*4,v);}for(r,v)in[(reg::CTRL,CTRL_USE_INTERNAL_DMA|CTRL_INT_ENABLE),(reg::BMOD,BMOD_DE),(reg::DBADDR,RAM),(reg::BLKSIZ,512),(reg::BYTCNT,512)]{self.put(SD+r,v);}self.cmd(n,7,CMD_RESP|CMD_DATA|if n==24{CMD_WRITE}else{0});assert_ne!(self.get(SD+reg::RINTSTS)&int::DATA_OVER,0);assert_eq!(self.get(RAM)&des0::OWN,0);}
 fn rmt(&mut self,bytes:[u8;3]){for(i,bit)in bytes.into_iter().flat_map(|b|(0..8).map(move|n|b&(0x80>>n)!=0)).enumerate(){let(hi,lo)=if bit{(64,32)}else{(32,64)};self.put(0x6001_6800+i as u32*4,0x8000|hi|lo<<16);}self.put(0x6001_6860,0);self.put(0x6001_6020,1<<16|1<<8|1);self.m.bus.tick(100_000);self.m.bus.board.advance_to(self.m.bus.cycles);}
}
#[test]fn actual_lx7_both_4g_rgb_outputs_obey_grb_route_and_cold_restart(){for name in BOARDS{let mut g=Guest::new(name);g.route(37,81);g.rmt([0x22,0x11,0x33]);assert_eq!(g.m.bus.board.leds().unwrap().1,0);g.route(37,256);g.route(38,81);g.rmt([0x22,0x11,0x33]);assert_eq!(g.m.bus.board.leds().unwrap().0,[[0x11,0x22,0x33]]);assert!(g.m.bus.board.display().is_none());let cold=Guest::new(name);assert_eq!(cold.m.bus.board.leds().unwrap().0,[[0;3]]);}}
#[test]fn actual_lx7_both_4g_native_one_bit_tf_sector_io_wrong_route_width_and_eject(){for name in BOARDS{let mut g=Guest::new(name);assert_eq!(g.m.bus.board.sd_card_slot(),Some(([5,4,6,255,255,255],false)));g.m.bus.attach_sd_card(Box::new(sdmmc::MemStore(vec![0;1<<20])),Default::default()).unwrap();g.sd_wiring();g.ready();for i in 0..128{g.put(RAM+512+4*i,i.wrapping_mul(0x1020_4081));}g.sector(24,RAM+512);g.sector(17,RAM+1024);for i in 0..128{assert_eq!(g.get(RAM+1024+4*i),i.wrapping_mul(0x1020_4081));}assert_eq!(g.m.bus.periph.sdmmc.stats.bytes_written,512);assert_eq!(g.m.bus.periph.sdmmc.stats.bytes_read,512);for(signal,pin)in[(179,3),(213,41)]{g.put(0x6000_4154+4*signal,0x80|pin);g.cmd(8,0x1aa,CMD_RESP);assert_ne!(g.get(SD+reg::RINTSTS)&int::RTO,0);g.sd_wiring();}g.put(SD+reg::CTYPE,2);g.cmd(8,0x1aa,CMD_RESP);assert_ne!(g.get(SD+reg::RINTSTS)&int::RTO,0);g.put(SD+reg::CTYPE,0);g.m.bus.board.set_sd_card_present(false);g.cmd(8,0x1aa,CMD_RESP);assert_ne!(g.get(SD+reg::RINTSTS)&int::RTO,0);assert!(g.m.bus.board.i2c_devices().is_empty());}}
